CREATE OR ALTER PROCEDURE [dbo].[uspPurchaseRequest_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @RequestedByEmployeeId UNIQUEIDENTIFIER = NULL
	, @RequestNumber NVARCHAR(MAX) = NULL
	, @RequestDate DATETIME = NULL
	, @RequiredDate DATETIME2 = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[RequestDate]
			, t.[Status]
			, t.[Note]
			, t.[RequestNumber]
			, t.[RequestedByEmployeeId]
			, t.[RequiredDate]
			, t.[CreatedDate]
		FROM [dbo].[PurchaseRequest] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[RequestNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@RequestedByEmployeeId IS NULL OR t.[RequestedByEmployeeId] = @RequestedByEmployeeId)
			AND (ISNULL(@RequestNumber, '') = '' OR t.[RequestNumber] LIKE CONCAT('%', @RequestNumber, '%'))
			AND (@RequestDate IS NULL OR t.[RequestDate] = @RequestDate)
			AND (@RequiredDate IS NULL OR t.[RequiredDate] = @RequiredDate)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestDate' THEN r.[RequestDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestDate' THEN r.[RequestDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestNumber' THEN r.[RequestNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestNumber' THEN r.[RequestNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestedByEmployeeId' THEN r.[RequestedByEmployeeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestedByEmployeeId' THEN r.[RequestedByEmployeeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requiredDate' THEN r.[RequiredDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requiredDate' THEN r.[RequiredDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
